function validate([s]) {
  if (typeof s !== 'string' || s.length < 1 || s.length > 1000) return 's must have 1 to 1000 characters.';
  if (!/^[a-z|*]+$/.test(s)) return 's may contain only lowercase letters, | and *.';
  if ((s.match(/\|/g) || []).length % 2 !== 0) return 's must contain an even number of | characters.';
  return null;
}

