function generate(rand, size) {
  const n = size === 'large' ? 1000 : 1 + Math.floor(rand() * 12);
  const barRate = rand() * 0.4;
  const starRate = rand() * 0.5;
  const chars = [];
  for (let i = 0; i < n; i++) {
    const r = rand();
    if (r < barRate) chars.push('|');
    else if (r < barRate + starRate) chars.push('*');
    else chars.push(String.fromCharCode(97 + Math.floor(rand() * 26)));
  }
  // An odd number of bars is fixed by turning one bar into a letter.
  if (chars.filter(c => c === '|').length % 2 === 1) chars[chars.indexOf('|')] = 'x';
  return [chars.join('')];
}
